import{R as e,e as o,f as n,U as i}from"./chunks/framework.ywem4qy5.js";const p=JSON.parse('{"title":"Zoho","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/zoho.md","filePath":"integrations/crm/zoho.md","lastUpdated":1775908585000}'),r={name:"integrations/crm/zoho.md"};function a(l,t,s,h,c,g){return o(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="zoho" tabindex="-1">Zoho <a class="header-anchor" href="#zoho" aria-label="Permalink to &quot;Zoho&quot;">​</a></h1><p>Follow the below steps to connect to the Zoho API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Zoho as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-zoho-api" tabindex="-1">Step 2. Connect to the Zoho API <a class="header-anchor" href="#step-2-connect-to-the-zoho-api" aria-label="Permalink to &quot;Step 2. Connect to the Zoho API&quot;">​</a></h3><ol><li>Go to <a href="https://accounts.zoho.com/developerconsole" target="_blank">Zoho API Console</a> and login to your account.</li><li>Click the <strong>Add Client</strong> button.</li><li>Click <strong>Server-based Applications</strong>.</li><li>In the <strong>Authorized Redirect URIs</strong> field, enter the value from the <strong>Redirect URI</strong> field in Formie.</li><li>Copy the <strong>Client ID</strong> from Zoho and paste in the <strong>Client ID</strong> field in Formie.</li><li>Copy the <strong>Client Secret</strong> from Zoho and paste in the <strong>Client Secret</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li><li>You‘ll be redirected to Zoho, where you must approve Formie to access your Zoho account.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const m=e(r,[["render",a]]);export{p as __pageData,m as default};
